import{_ as d,o as e,c as r,ag as o}from"./chunks/framework.Pp2klvcf.js";const u=JSON.parse('{"title":"认证与 RBAC","description":"","frontmatter":{},"headers":[],"relativePath":"zh/server/api/auth-rbac.md","filePath":"zh/server/api/auth-rbac.md","lastUpdated":1788681727000}'),a={name:"zh/server/api/auth-rbac.md"};function c(s,t,i,n,p,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="认证与-rbac" tabindex="-1">认证与 RBAC <a class="header-anchor" href="#认证与-rbac" aria-label="Permalink to &quot;认证与 RBAC&quot;">​</a></h1><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/v1/auth/login</code></td><td>登录并返回 Access/Refresh Token</td></tr><tr><td>POST</td><td><code>/api/v1/auth/register</code></td><td>注册普通用户，无需 Bearer Token</td></tr><tr><td>POST</td><td><code>/api/v1/auth/refresh</code></td><td>轮换令牌</td></tr><tr><td>POST</td><td><code>/api/v1/auth/logout</code></td><td>撤销 Refresh Token</td></tr><tr><td>GET</td><td><code>/api/v1/auth/me</code></td><td>当前用户、角色与权限</td></tr><tr><td>GET/POST</td><td><code>/api/v1/users</code></td><td>用户分页/创建</td></tr><tr><td>GET/PUT/DELETE</td><td><code>/api/v1/users/{id}</code></td><td>用户详情/更新/删除</td></tr><tr><td>GET/POST</td><td><code>/api/v1/roles</code></td><td>角色分页/创建</td></tr><tr><td>GET/PUT/DELETE</td><td><code>/api/v1/roles/{id}</code></td><td>角色详情/更新/删除</td></tr><tr><td>GET</td><td><code>/api/v1/permissions</code></td><td>权限列表</td></tr><tr><td>GET</td><td><code>/api/v1/menus</code></td><td>当前用户菜单树</td></tr><tr><td>GET</td><td><code>/api/v1/menus/tree</code></td><td>管理端完整菜单树</td></tr></tbody></table><p>Access Token 放在 <code>Authorization: Bearer &lt;token&gt;</code>。Refresh Token 只用于刷新与登出，不应作为普通资源凭证。</p><p>JWT 过滤器只接受 <code>type=access</code>，Refresh Token 不能作为资源凭证。Spring Security 使用第一个匹配规则，因此公开白名单保持在 <code>anyRequest().authenticated()</code> 之前；401 与 403 都返回统一 <code>ApiResponse</code>。</p><p><code>analytics:view</code> 与 <code>data:view</code> 分别保护经营分析和数据中心。<code>GET /api/v1/menus</code> 只要求登录，因为它返回当前用户自己的导航；<code>/menus/tree</code> 与菜单 CRUD 仍使用 <code>menu:*</code> 权限。</p>',5)])])}const l=d(a,[["render",c]]);export{u as __pageData,l as default};
